def topic(title,children=None,notes=None):
 d={"id":str(uuid.uuid4()),"class":"topic","title":title}
 if children:d["children"]={"attached":children}
 if notes:d["notes"]={"plain":{"content":notes}}
 return d
def sheet(title,root): return {"id":str(uuid.uuid4()),"class":"sheet","title":title,"rootTopic":root}

